    public static function svg(string $name, string $class = 'ico'): string
    {
        $p = self::PATHS[$name] ?? self::PATHS['sparkles'];
        return '<svg class="' . htmlspecialchars($class, ENT_QUOTES) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $p . '</svg>';
    }

    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
